        ctx.fillStyle = i % 2 ? '#7fb268' : '#8fc0a0';
        ctx.beginPath(); ctx.ellipse(sx + bend, y - 14 * s - h, 3.5 * s, 5 * s, 0, 0, Math.PI * 2); ctx.fill();
