      const gg = ctx.createRadialGradient(b.x, b.y + bob, 2, b.x, b.y + bob, 22);
      const coinBubble=(b.icon||'🪙')==='🪙';
       gg.addColorStop(0,coinBubble?'rgba(255,235,165,.95)':'rgba(255,235,150,.95)');
