      ctx.fillStyle='#84624d';ctx.font='bold 20px Cat Bond Nunito, Yuanti SC, PingFang SC, Microsoft YaHei, Noto Sans CJK SC, sans-serif';ctx.textAlign='center';
      ctx.fillText('↓',hide.spot.x,hide.spot.y-47);
